package com.supermarkettracker.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="item_venda") public class ItemVendaEntity { @Id public UUID id; @Column(name="venda_id",nullable=false) public UUID vendaId; @Column(name="produto_id") public UUID produtoId; @Column(name="item_numero",nullable=false) public int numero; @Column(name="produto_nome",nullable=false,length=200) public String produtoNome; @Column(name="codigo_barras",length=100) public String codigoBarras; @Column(name="unidade_medida",nullable=false,length=10) public String unidadeMedida; @Column(nullable=false,precision=14,scale=3) public BigDecimal quantidade; @Column(name="preco_unitario",nullable=false,precision=14,scale=2) public BigDecimal precoUnitario; @Column(name="preco_compra_unitario",nullable=false,precision=14,scale=2) public BigDecimal precoCompraUnitario; @Column(nullable=false,precision=14,scale=2) public BigDecimal desconto; @Column(nullable=false,precision=14,scale=2) public BigDecimal acrescimo; @Column(nullable=false,precision=14,scale=2) public BigDecimal subtotal; @Column(name="custo_total",nullable=false,precision=14,scale=2) public BigDecimal custoTotal; @Column(nullable=false,precision=14,scale=2) public BigDecimal lucro; @Column(name="created_at",nullable=false) public Instant criadoEm; public ItemVendaEntity() {} }
